Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1000111;
const long long MOD = 1000000007;

long long visited[MAXN], countMap[MAXN];

long long modExponentiation(long long base, int exponent) {
    long long res = 1;
    while (exponent > 0) {
        if (exponent & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exponent >>= 1;
    }
    return res;
}

int main() {
    int p, k;
    cin >> p >> k;
    if (k == 0) {
        cout << modExponentiation(p, p - 1) << endl;
        return 0;
    }
    if (k == 1) {
        cout << modExponentiation(p, p) << endl;
        return 0;
    }
    fill(visited, visited + p, 0);
    fill(countMap, countMap + p, 0);
    for (int start = 1; start < p; start++) {
        if (visited[start]) continue;
        long long current = start, length = 0;
        while (!visited[current]) {
            visited[current] = 1;
            current = (current * k) % p;
            length++;
        }
        countMap[length]++;
    }
    long long answer = 1;
    for (int len = 1; len <= p - 1; len++) {
        if (countMap[len] == 0) continue;
        long long tmp = modExponentiation((len * countMap[len] + 1) % MOD, countMap[len]);
        answer = (answer * tmp) % MOD;
    }
    cout << answer << endl;
    return 0;
}
</original_code>
